	    Page.env = "PSE22";
		Page.instanceId = "";
		if(Page.env.substring(0,3) == 'VSE'){
			Page.instanceId = 'ver-'
		}
   		nLogger.configure({
   			nth_service_id: Page.instanceId + "taxlaw.nts.go.kr", // 로그 생성 단위, 값 지정 필요. 각 사이트별로 다르게 설정. 예시: taxlaw.nts.go.kr
   			nth_logging_url_base_http: "https://" + Page.instanceId + "taxlaw.nts.go.kr/nlog", // 수집 서버 주소

   			nth_logging_url_base_https: "https://" + Page.instanceId + "taxlaw.nts.go.kr/nlog"// 수집 서버 주소

		});

   		if(typeof Page.getParameter().ntstDcmId == "undefined"){
   			nLogger.log();   			
   		}

	Page.envType = "SE";
	Page.scrnNm = "세법해석례상세";
	$(window).on("load", function(){
		if(Page.title.settingBool) {
			Page.title.setTitle(function(){
 	            return Page.scrnNm;
 	         });	
		}
	})

		Biz.paramsData = Page.getParameter();
		Biz.dcmFileInfo = [];
		Biz.pmsCodeList = [];
		Biz.dcmRegDt = "";
		Page.title.settingBool = false;

		CodeFactory.prepareCode("19378");
		CodeFactory.prepareCode("19387");
		CodeFactory.prepareCode("15917");
		CodeFactory.prepareCode("19374");
		CodeFactory.prepareCode("19375");


		Biz.scrnControll = {
			loadScrn : function(initFn){
				// 화면 로드시 이벤트
				var _this = this;

				_this.getCode();

				var tmplData = {};

				var actionId = "ASIQTB002PR01";
				var paramData = {};
				paramData["dcmDVO"] = Biz.paramsData;	
				Req.doAction(actionId,paramData)
				.done(function(data){
					var loadData = data[actionId];

					if(!loadData.dcmDVO && loadData.dcmDVO == null){
						Page.alert("등록된 게시물이 없습니다.",function(){
							this.close();
						});

						return;
					}

					var params = [];
					params["pageTtl"] = Biz.pmsCodeList["ntstDcmClCd"][loadData["dcmDVO"].ntstDcmClCd];
					params["ntstDcmId"] = loadData["dcmDVO"].ntstDcmId;

					loadData["dcmDVO"].ntstDcmTtl = loadData["dcmDVO"].ntstDcmTtl.replace(/&lt;/g,'<').replace(/&gt;/g,'>');
					// &lt;를 <, &gt;를 >로 변환
					params["ntstDcmTtl"] = loadData["dcmDVO"].ntstDcmTtl;
					params["ntstDcmDscmCntn"] =  loadData["dcmDVO"].ntstDcmDscmCntn
					params["ntstDcmClCd"] = loadData["dcmDVO"].ntstDcmClCd
					params["frsMateRgtDtm"] = loadData["dcmDVO"].frsRgtDtm
					params["ntstDcmRgtDt"] = loadData["dcmDVO"].ntstDcmRgtDt
					params["ntstDcmRplyCntn"] = loadData["dcmDVO"].ntstDcmRplyCntn
					initFn(params);

					Biz.dcmRegDt = loadData["dcmDVO"].ntstDcmRgtDt;

					tmplData["tmplCenter"] = {
						btns : [
							{
								btnNm : "요지"
								,btnId : "btn_linkGist"
								,btnOtp : {
									href : "javascript:;" 
									,title : "요지"
									,target : "_self"
									,"data-body-link-nm" : "body_content_gist"
								}
								,btnClass : "btn btn_clip"
							}							
							,{
								btnNm : function(code){
									switch (code) {
									case "01":
										return "답변내용";
									case "02":
										return "회신";
									case "03":
										return "회신";
									case "04":
										return "회신";
									case "05":
										return "결정내용 ";
									case "06":
										return "결정내용 ";
									case "07":
										return "결정내용 ";
									case "08":
										return "결정내용 ";
									case "09":
										return "판결내용 ";
									case "10":
										return "결정내용 ";
									}

								}(loadData["dcmDVO"].ntstDcmClCd)
								,btnId : "btn_linkCntn"
								,btnOtp : {
									href : "javascript:;" 
									,title : "답변내용"
									,target : "_self"
									,"data-body-link-nm" : "body_content_cntn"
								}
								,btnClass : "btn btn_clip"
							}
							,{
								btnNm : "상세내용"
								,btnId : "btn_linkHtmlCntn"
								,btnOtp : {
									href : "javascript:;" 
									,title : "상세내용"
									,target : "_self"
									,"data-body-link-nm" : "body_content_htmlCntn"
								}
								,btnClass : "btn btn_clip"
							}
						]
					}


					// 문서 첨부파일
					var dcmHtmlCntn = "";
					var dcmHwpEditorDVOList = loadData.dcmHwpEditorDVOList;
					if(dcmHwpEditorDVOList){
						$.each(dcmHwpEditorDVOList, function(idx, data){
							if(data.dcmFleTy == "hwp"){
								Biz.dcmFileInfo["hwp"] = {
									fleId : data.dcmFleId
									,fleSn : data.dcmFleSn
								};

							}else if(data.dcmFleTy == "html"){
								Biz.dcmFileInfo["html"] = {
									fleId : data.dcmFleId
									,fleSn : data.dcmFleSn
								};

								dcmHtmlCntn = function(centerHtml){
									var _$centerHtml = $("<div />").append(centerHtml);
									if(_$centerHtml.text() != ""){									
										var logImgDataStr = []; 
										logImgDataStr.push("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAKAAAAAfCAYAAABgU8aNAAAAAXNSR0IArs4c6QAAD9lJREFUeF7tXA");
										logImgDataStr.push("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA/8AAADUCAYAAADKgZM+AAAAAXNSR0IArs4c6QAAAARnQU1BAACxjw");
										logImgDataStr.push("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAHUAAAAaCAYAAACJphMzAAAAAXNSR0IArs4c6QAAEJZJREFUaEPtWX");
										logImgDataStr.push("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAKgAAAAWCAYAAABUi9exAAAAAXNSR0IArs4c6QAADxVJREFUaEPtW2");
										logImgDataStr.push("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAKAAAAAfCAYAAABgU8aNAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjw");

										_$centerHtml.find("img").each(function(){
											if($(this).attr("alt") == ""){
											    if(logImgDataStr.indexOf($(this).attr("src").substring(0,100)) >= 0){
											        $(this).attr("alt","국세법령정보시스템");
											    }else{
											    	$(this).attr("alt",loadData.dcmDVO.ntstDcmTtl);									    	
											    }
											}
										});
									}else{
										_$centerHtml.text("상세내용이 없습니다.");
									}

									return _$centerHtml.html();

								}(data.dcmFleByte); 
							}

						})
					}

					tmplData["tmplOpt"] = {
							dcmClCd : loadData["dcmDVO"]["ntstDcmClCd"]
					}

					var wordListYn = false;

					if(loadData["dcmRltnStttMatrList"]){
						if(loadData["dcmRltnStttMatrList"].length > 0){
							wordListYn = true;
						}
					}

					if(loadData["dcmRltnStttList"]){
						if(loadData["dcmRltnStttList"].length > 0){
							wordListYn = true;
						}
					}

					tmplData["tmplLeft"] = {};
					tmplData["tmplLeft"]["data"] = {
						trilPsagList : loadData["trilPsagList"] // 재판경과	
						,rfrnPrtsList : loadData["dcmRfrnPrtsList"] // 참조판례
						,qutPrtsList : loadData["dcmQutPrtsList"]   // 인용판례							
					}

					if(loadData["dcmDVO"].ntstDcmClCd == "07" || loadData["dcmDVO"].ntstDcmClCd == "08" || loadData["dcmDVO"].ntstDcmClCd == "09"){
						if(loadData["dcmDVO"].ntstLwsDfntYn =="Y"){
							loadData["dcmDVO"]["ntstLwsDfntNm"] = "완료";
						}else{
							loadData["dcmDVO"]["ntstLwsDfntNm"] = "진행중";
						}	
					}

					tmplData["tmplCenter"]["data"] = {
						dcmData : loadData["dcmDVO"] // 문서정보
						,dcmHtmlCntn: dcmHtmlCntn //문서 상세내용
						,wordListYn : wordListYn
						,rltnStttMatrList : loadData["dcmRltnStttMatrList"]  // 주제어
						,rltnStttList: loadData["dcmRltnStttList"]  // 관련법령
					};

					// 템플릿 생성
					var _$mainTmpl = _this.makeMainTmpl(tmplData);

					//상세화면 열기
					_$mainTmpl.find("[data-openpopup-dcmid]").click(function(){
						Page.openPopup("/qt/USEQTA002P.do", {
							title : $(this).data("openpopupDcmid")
							,width : "1830px"
							,height : "965px"
							,param : {ntstDcmId :  $(this).data("openpopupDcmid"),wnkey : Biz.paramsData.wnkey}
						});			//param 받는 형식 추후에 변경해야함			
					})


					//주제어 화면 열기
					_$mainTmpl.find("[data-ntst-matr-uqno]").click(function(){
						Page.openPopup("/pd/USEPDI002P.do", {
							title : $(this).text()
							,width : "1830px"
							,height : "965px"
							,param : {
								ntstUqno :  $(this).data("ntstMatrUqno")
								,matr :  $(this).text()
								,rltn : 'matrClus'
							}
						});			//param 받는 형식 추후에 변경해야함			
					});

					//관련법령 화면 열기
					_$mainTmpl.find("[data-ntst-sttt-linkNm]").click(function(){
						var ntstNm = $(this).text();
						var paramData = {};
						var actionId = 'ASISTA002MR04'

						paramData['ntstNm'] = ntstNm;
						paramData['ntstEnfrDt'] = Util.formatDocumentDate(Biz.dcmRegDt);

						var searchDeffer = Req.doAction(actionId, paramData);
						searchDeffer.done(function(data){ //액션 처리후의 콜백 실행
							var d = data[actionId];
							var dvo = d.txaStttDVO;
							if(dvo != null){
								Page.openWindow('/st/USESTA002P.do', {
									 "ntstBscId" : dvo.ntstBscId // 국세법령명
									, "ntstSysClCd" : dvo.ntstSysClCd // 국세법령체계구분코드
									, "ntstTlawClCd" : dvo.ntstTlawClCd // 국세법령세법구분코드
									, "ntstTextUqno" : d.ntstTextUqno // 국세법령조문
									,"ntstEnfrDt" : Util.formatDocumentDate(Biz.dcmRegDt)
								},"width="+(screen.width-20)+",height="+(screen.height-20)+",top=0,left=0,scrollbars=yes");
							}else{
								Page.alert("관련법령을 불러오는중 오류가 발생하였습니다.\n잠시후 다시 시도 부탁드립니다.")
							}
						});
					}); 



					_$mainTmpl.find("[data-body-link-nm]").click(function(){
						var linkNm = $(this).data("bodyLinkNm");
						var _$linkTag = $("[data-center-type='".concat(linkNm,"']"));

						_$linkTag.parent().scrollTop(0);

						var linkFirstOffTop = $("[data-center-type].word_group").eq(0).offset().top;
						var thisOffSetTop = _$linkTag.offset().top;

						$("[data-center-type]").parent().scrollTop(thisOffSetTop - linkFirstOffTop);					

						_$linkTag.siblings().find("h4").removeAttr("tabindex");
						_$linkTag.find("h4").attr("tabindex","0");
						_$linkTag.find("h4").focus();				
					});

					_$mainTmpl.find("#btn_showCntnView").click(function(){
						var viewTy = $(this).data("viewTy");

						if(typeof viewTy == "undefined" && !Biz.pdfViewer){
							Biz.pdfViewer = new PDFViewer(_$mainTmpl.find("#cntnWrap_pdf"), { width : "100%", height : "100%" });
							Biz.pdfViewer.init(function(){
								Biz.pdfViewer.getFile(Biz.dcmFileInfo["hwp"].fleId, Biz.dcmFileInfo["hwp"].fleSn);
							});

							viewTy = "html";
						}

						if(viewTy == "html"){
							$(this).text("HTML로 보기");
							$(this).removeClass("btn_view_pdf");
							$(this).addClass("btn_view_html");
							_$mainTmpl.find("#cntnWrap_html").addClass("del");
							_$mainTmpl.find("#cntnWrap_pdf").removeClass("del");							
							$(this).data("viewTy", "pdf");
						}else{
							$(this).text("PDF로 보기");
							$(this).removeClass("btn_view_html");
							$(this).addClass("btn_view_pdf");
							_$mainTmpl.find("#cntnWrap_pdf").addClass("del");
							_$mainTmpl.find("#cntnWrap_html").removeClass("del");							
							$(this).data("viewTy", "html");
						}	
					});

					_$mainTmpl.find("#btn_showToolTip").click(function(){
						if($(this).hasClass("active")){
							return;	
						}

						$(this).addClass("active");
						$("#toolTipCntn").addClass("on");
					});

					_$mainTmpl.find("#btn_hideToolTip").click(function(){
						$("#btn_showToolTip").removeClass("active");
						$("#toolTipCntn").removeClass("on");
					});

					$("#dcmDetailBox").append(_$mainTmpl);

					var wisenutActionId = "ASIQTB002PR03";
					var wisenutParam= {};
					wisenutParam["dcmDVO"] = {
						ntstDcmId : loadData["dcmDVO"].ntstDcmId
						,ntstDcmTtl : loadData["dcmDVO"].ntstDcmTtl
						,ntstDcmClCd : loadData["dcmDVO"].ntstDcmClCd
						,ntstDcmGistCntn : loadData["dcmDVO"].ntstDcmGistCntn
					};
					Req.doAction(wisenutActionId, wisenutParam)
					.done(function(data){
						var result = data[wisenutActionId];

						tmplData["tmplRight"] = {};
						tmplData["tmplRight"]["data"] = {
								ideskList : result["ideskResultVO"],
								teaExtractKeywordList : result["teaExtractKeywordResultVO"]
						};

						var _$rightTmpl = _this.makeWisenutTmpl(tmplData);

						//상세화면 열기
						_$rightTmpl.find("[data-openpopup-dcmid]").click(function(){
							Page.openPopup("/qt/USEQTA002P.do", {
								title : $(this).data("openpopupDcmid")
								,width : "1830px"
								,height : "965px"
								,param : {ntstDcmId :  $(this).data("openpopupDcmid"),wnkey : Biz.paramsData.wnkey}
							});			//param 받는 형식 추후에 변경해야함			
						})


						_$rightTmpl.find("#btn_openTagCloud").click(function(){
							if($("#tagCloudBox").hasClass("active")){
								return;
							}
							$("#tagCloudBox").addClass("active");
							$("#tagCloudBox #tagcloud").find("canvas").remove();

							var tagCloudEvent = function(){
								$("#tagCloudBox #tagcloud").awesomeCloud({
									"size" : {
										"grid" : 10,
										"normalize" : false
									},
									"options" : {
										"color" : "random-dark",
										"rotationRatio" : 0,
										"printMultiplier" : 3
									},
									"font" : "'NotoSansM', 'sans-serif'",
									"shape" : "square"
								});
							}();

						})

						_$rightTmpl.find("#btn_closeTagCloud").click(function(){
							$("#tagCloudBox #tagcloud").find("canvas").remove();
							$("#tagCloudBox").removeClass("active");
						})

						var _$tmpTightTmpl = $("#dcmDetailBox .div_wrap .board_right_wrap");

						if(_$tmpTightTmpl.length > 0) {
							_$tmpTightTmpl.replaceWith(_$rightTmpl)
						} else {
							$("#dcmDetailBox .div_wrap").append(_$rightTmpl);
						}


						var tagScript = document.createElement('script');
						tagScript.type = 'text/javascript';
						tagScript.async = true;
						tagScript.src = "/js/vendor/awesomeCloud/jquery.awesomeCloud-0.2.js";
				    	var tagScriptResult = document.getElementsByTagName('script')[0];
				    	tagScriptResult.parentNode.insertBefore(tagScript, tagScriptResult);
					})


				     _this.resizeScrn();
				     $("[data-name='lawLinkSpan']").css({"color":"#4e6db8", "font-weight":"600"});


				     var logList = ["01","02","03","04","05","06","07","08","09","10"];

				     if(Biz.paramsData.wnkey && logList.indexOf(loadData["dcmDVO"].ntstDcmClCd) >= 0){
					     //와이즈넛 로그 쌓기
					     var collection = "";
					     if(parseInt(loadData["dcmDVO"].ntstDcmClCd) < 5){
					    	 collection = "question,question_gr";
					     }else if(parseInt(loadData["dcmDVO"].ntstDcmClCd) <= 10){
					    	 collection = "precedent,precedent_gr";
					     }

					     obj = {				    		 
					    	DOCID : "001_" + loadData["dcmDVO"].ntstDcmId
					    	,wnKey : Biz.paramsData.wnkey
					     };

					     LinkBroker.totalSearch.createLog(obj, collection);
				     }

				     nLogger.params({ntstDcmClCd :loadData["dcmDVO"].ntstDcmClCd});
				     nLogger.log();
				})
			}
			,makeMainTmpl : function(data){

				_$extndData = $.extend(true,{
					tmplOpt :{
						tmplTy : "type2"
						,envType : Page.envType
					}
				},data)

				var leftTmplDcmClCd = ["08","09"];

				var detailTmpl = Page.getHtmlTemplateById("dcmViewBoxTmpl");
    			var hadleBarsBind = Handlebars.compile(detailTmpl);
    			var leftTmplHtml = "";   			

    			if(leftTmplDcmClCd.indexOf(data["tmplOpt"]["dcmClCd"]) >= 0){
    				leftTmplHtml = Page.getHtmlTemplateById("dcmViewLeftTmpl")
    				_$extndData["tmplOpt"]["tmplTy"] = "type1";
				}

    			var rightTmplHtml = Page.getHtmlTemplateById("dcmViewRightTmpl");
    			var rightHandlebarsBind = Handlebars.compile(rightTmplHtml);
    			var emptyRightHtml = rightHandlebarsBind({
    				tmplOpt: { envType : Page.envType },
    				data : {
    					ideskList : [],
    					teaExtractKeywordList: []
    				}
    			});

    			Handlebars.registerPartial("left",leftTmplHtml);
    			Handlebars.registerPartial("center",Page.getHtmlTemplateById("dcmViewCenterTmpl"));
    			Handlebars.registerPartial("right",emptyRightHtml);
    			var _$result = $(hadleBarsBind(_$extndData));

    			return _$result;

			}
			,makeWisenutTmpl : function(data) {

				_$extndData = $.extend(true,{
					tmplOpt :{
						tmplTy : "type2"
						,envType : Page.envType
					}
				},data)

				var noRightTmplDcmClCd = ["11","12","13","14"];
				if(noRightTmplDcmClCd.indexOf(data["tmplOpt"]["dcmClCd"]) >= 0){
    				rightTmplHtml = "";
    				_$extndData["tmplOpt"]["tmplTy"] = "type0";
				}   	
				var rightTmplHtml = Page.getHtmlTemplateById("dcmViewRightTmpl");
				var hadleBarsBind = Handlebars.compile(rightTmplHtml);

    			Handlebars.registerPartial("right",rightTmplHtml);

    			return $(hadleBarsBind(_$extndData));
			}
			,getCode : function(){

				//문서
	   			Biz.pmsCodeList["ntstDcmClCd"] = Biz.dcmCommonFunc.getPmsCodeList({
	   				pmsCodeList : ["01","02","03","04","05","06","07","08","09","10","11","12","13","14","41"] 
	   				,commCode : "19378"
	   			});

				//세목
				Biz.pmsCodeList["ntstTlawClCd"] = Biz.dcmCommonFunc.getPmsCodeList({
	   				pmsCodeList : ["112","115","116","117","202","203","205","206","210","213","301","302","303","304","305","306","307","308","309","310","311","312","313","314","999"]
	   				,commCode : "19387"
	   			},"Abrv");


				Biz.pmsCodeList["ntstDcmIntcClCd"] = Biz.dcmCommonFunc.getCodeDataList("19374"); // 심급구분
				Biz.pmsCodeList["ntstDcmDcsClCd"] = Biz.dcmCommonFunc.getCodeDataList("19375"); // 결정구분			
				Biz.pmsCodeList["stttInfpClCd"] = Biz.dcmCommonFunc.getCodeDataList("15917"); // 공개구분
			}
			,resizeScrn : function(){
				var wrapHig = $("[data-center-type='wrap']").css("height").replace("px","");

				console.log("wrapHig : " + wrapHig);

				var _$reject = $("[data-center-type='reject']");
				var rejectHig = 0;

				if(_$reject.length > 0){
					rejectHig = parseInt(_$reject.css("height").replace("px",""));
				}

				var _$head = $("[data-center-type='head']");
				var headHig = parseInt(_$head.css("height").replace("px",""));

				var _$word = $("[data-center-type='word']");
				var wordHig = 0;
				if(_$word.length > 0){
					wordHig = parseInt(_$word.css("height").replace("px",""));
				}

				var bodyHig = (wrapHig - rejectHig - headHig - wordHig);
				console.log("bodyHig : " + bodyHig );

