Biz.setSubMenuMark = function(){
	var list = $('[data-type="subMenuSch"]');
	if($('[data-type="subMenuSch"].bg_orange').length == 0){
		list.eq(0).addClass('bg_orange');
		list.eq(0).removeClass('bg_yellow');
	}else{
		var cnt = 0;
		var resultNum = 0;
		list.each(function(){
		    if($(this).is('.bg_orange')){
		    	resultNum = cnt
		    }
		    cnt++
		})
		list.eq(resultNum).addClass('bg_yellow');
		list.eq(resultNum).removeClass('bg_orange');
		resultNum++;
		if(list.eq(resultNum).length > 0){
			list.eq(resultNum).addClass('bg_orange');
			list.eq(resultNum).removeClass('bg_yellow');
			Biz.setSubScrollHeight(list.eq(resultNum));
		}else{
			list.eq(0).addClass('bg_orange');
			list.eq(0).removeClass('bg_yellow');
			Biz.setSubScrollHeight(list.eq(0))
		}

	}
}

Biz.setSubScrollHeight = function(obj){
	//내부 스크롤 있을때
	if(obj.parents('.vertical_scroll').length > 0){
		obj.parents('.vertical_scroll').animate({
			scrollTop : obj.offset().top - obj.parents('.vertical_scroll').offset().top + obj.parents('.vertical_scroll').scrollTop()
		})
	}else{
		$('#content').animate({
			scrollTop : obj.offset().top - 185
		})
	}
}

